#pragma once
#include "mapping_layout.hpp"
#include <cstring>
#include <vector>
struct CreationConfig { uint32_t lanes,endpoints,responses,snapshots,laneDepth,c2aDepth; uint64_t executionId; };
struct MappingView { const lasec_at_control_page* control=nullptr; const lasec_at_endpoint_descriptor* endpoints=nullptr; const lasec_at_lane_descriptor* lanes=nullptr; const lasec_at_response_slot* responses=nullptr; const lasec_at_snapshot_descriptor* snapshots=nullptr; const lasec_at_c2a_descriptor* c2a=nullptr; };
inline bool serializeContainer(const CreationConfig& cfg,std::vector<uint8_t>& bytes,MappingLayout& layout){if(!cfg.executionId||!buildMappingLayout(cfg.lanes,cfg.endpoints,cfg.responses,cfg.snapshots,cfg.laneDepth,cfg.c2aDepth,layout))return false;bytes.assign((size_t)layout.total,0);auto*c=reinterpret_cast<lasec_at_control_page*>(bytes.data());c->magic=LASEC_AT_MAGIC;c->abi_major=LASEC_AT_ABI_MAJOR;c->abi_minor=LASEC_AT_ABI_MINOR;c->mapping_bytes=layout.total;c->execution_id=cfg.executionId;c->lane_count=cfg.lanes;c->response_slot_count=cfg.responses;c->descriptor_count=cfg.endpoints;c->descriptor_capacity=cfg.endpoints;c->descriptor_offset=layout.endpoints.offset;c->endpoint_count=cfg.endpoints;c->snapshot_count=cfg.snapshots;c->lane_descriptor_offset=layout.laneDescriptors.offset;c->response_slot_offset=layout.responses.offset;c->snapshot_descriptor_offset=layout.snapshotDescriptors.offset;c->c2a_descriptor_offset=layout.c2aDescriptor.offset;auto*ep=reinterpret_cast<lasec_at_endpoint_descriptor*>(bytes.data()+layout.endpoints.offset);for(uint32_t i=0;i<cfg.endpoints;i++){ep[i].endpoint_id=i;ep[i].q2c_offset=layout.q2cSlots[i%cfg.lanes].offset;ep[i].q2c_depth=cfg.laneDepth;ep[i].event_stride=sizeof(lasec_at_event);ep[i].payload_limit=LASEC_AT_EVENT_PAYLOAD;ep[i].snapshot_offset=i<cfg.snapshots?layout.snapshots.offset+i*sizeof(lasec_at_snapshot):0;}auto*ld=reinterpret_cast<lasec_at_lane_descriptor*>(bytes.data()+layout.laneDescriptors.offset);for(uint32_t i=0;i<cfg.lanes;i++){ld[i].metadata={layout.lanes.offset+i*sizeof(lasec_at_ring_header),sizeof(lasec_at_ring_header),sizeof(lasec_at_ring_header),1};ld[i].events={layout.q2cSlots[i].offset,layout.q2cSlots[i].bytes,sizeof(lasec_at_event),cfg.laneDepth};ld[i].depth=cfg.laneDepth;ld[i].event_stride=sizeof(lasec_at_event);}auto*sd=reinterpret_cast<lasec_at_snapshot_descriptor*>(bytes.data()+layout.snapshotDescriptors.offset);for(uint32_t i=0;i<cfg.snapshots;i++)sd[i].storage={layout.snapshots.offset+i*sizeof(lasec_at_snapshot),sizeof(lasec_at_snapshot),sizeof(lasec_at_snapshot),1};auto*ad=reinterpret_cast<lasec_at_c2a_descriptor*>(bytes.data()+layout.c2aDescriptor.offset);ad->metadata={layout.c2aMetadata.offset,sizeof(lasec_at_ring_header),sizeof(lasec_at_ring_header),1};ad->events={layout.c2aSlots.offset,layout.c2aSlots.bytes,sizeof(lasec_at_event),cfg.c2aDepth};ad->depth=cfg.c2aDepth;ad->event_stride=sizeof(lasec_at_event);return true;}
inline bool validateWireContainer(const uint8_t* b,uint64_t n,MappingView& v){v={};if(!b||n<sizeof(lasec_at_control_page))return false;auto*c=reinterpret_cast<const lasec_at_control_page*>(b);if(c->magic!=LASEC_AT_MAGIC||c->abi_major!=LASEC_AT_ABI_MAJOR||c->abi_minor>LASEC_AT_ABI_MINOR||c->mapping_bytes!=n||!c->execution_id||!c->lane_count||c->lane_count>LASEC_AT_MAX_LANES||c->endpoint_count>c->descriptor_capacity||c->endpoint_count>LASEC_AT_MAX_ENDPOINTS||c->descriptor_capacity>LASEC_AT_MAX_ENDPOINTS||c->response_slot_count> LASEC_AT_MAX_RESPONSES||c->response_slot_count!=c->lane_count||c->snapshot_count>LASEC_AT_MAX_SNAPSHOTS||c->capability_bits&~LASEC_AT_CAP_KNOWN_MASK)return false;auto ok=[&](uint64_t o,uint64_t z,uint64_t a){return a&&o%a==0&&o<=n&&z<=n-o;};if(!ok(c->descriptor_offset,uint64_t(c->descriptor_capacity)*sizeof(lasec_at_endpoint_descriptor),64)||!ok(c->lane_descriptor_offset,uint64_t(c->lane_count)*sizeof(lasec_at_lane_descriptor),64)||!ok(c->response_slot_offset,uint64_t(c->response_slot_count)*sizeof(lasec_at_response_slot),64)||!ok(c->snapshot_descriptor_offset,uint64_t(c->snapshot_count)*sizeof(lasec_at_snapshot_descriptor),64)||!ok(c->c2a_descriptor_offset,sizeof(lasec_at_c2a_descriptor),64))return false;auto*lanes=reinterpret_cast<const lasec_at_lane_descriptor*>(b+c->lane_descriptor_offset);auto ring=[&](const lasec_at_region_descriptor&m,const lasec_at_region_descriptor&e,uint32_t d,uint32_t s){return d&&d<=1024&&!(d&(d-1))&&s==sizeof(lasec_at_event)&&m.stride==sizeof(lasec_at_ring_header)&&m.count==1&&e.stride==sizeof(lasec_at_event)&&e.count==d&&ok(m.offset,m.bytes,8)&&ok(e.offset,e.bytes,64)&&m.bytes==sizeof(lasec_at_ring_header)&&e.bytes==uint64_t(d)*sizeof(lasec_at_event);};for(uint32_t i=0;i<c->lane_count;i++)if(!ring(lanes[i].metadata,lanes[i].events,lanes[i].depth,lanes[i].event_stride))return false;auto*c2a=reinterpret_cast<const lasec_at_c2a_descriptor*>(b+c->c2a_descriptor_offset);if(!ring(c2a->metadata,c2a->events,c2a->depth,c2a->event_stride))return false;auto*ep=reinterpret_cast<const lasec_at_endpoint_descriptor*>(b+c->descriptor_offset);for(uint32_t i=0;i<c->endpoint_count;i++){if(ep[i].endpoint_id!=i||!ep[i].q2c_depth||ep[i].q2c_depth>1024||ep[i].event_stride!=sizeof(lasec_at_event)||ep[i].payload_limit>LASEC_AT_EVENT_PAYLOAD||!ok(ep[i].q2c_offset,uint64_t(ep[i].q2c_depth)*ep[i].event_stride,64))return false;bool q=false;for(uint32_t j=0;j<c->lane_count;j++)q=q||(ep[i].q2c_offset==lanes[j].events.offset&&ep[i].q2c_depth==lanes[j].depth);if(!q)return false;}v={c,ep,lanes,reinterpret_cast<const lasec_at_response_slot*>(b+c->response_slot_offset),reinterpret_cast<const lasec_at_snapshot_descriptor*>(b+c->snapshot_descriptor_offset),c2a};return true;}
inline bool validateWireContainerComplete(const uint8_t* b,uint64_t n,MappingView& v){v={};MappingView x;if(!validateWireContainer(b,n,x))return false;auto ok=[&](uint64_t o,uint64_t z,uint64_t a){return a&&o%a==0&&o<=n&&z<=n-o;};for(uint32_t i=0;i<x.control->snapshot_count;i++){auto&s=x.snapshots[i].storage;if(s.count!=1||s.stride!=sizeof(lasec_at_snapshot)||s.bytes!=sizeof(lasec_at_snapshot)||!ok(s.offset,s.bytes,8))return false;}for(uint32_t i=0;i<x.control->endpoint_count;i++){auto&e=x.endpoints[i];bool ref=e.snapshot_offset==0;for(uint32_t j=0;j<x.control->snapshot_count;j++)ref=ref||e.snapshot_offset==x.snapshots[j].storage.offset;if(e.endpoint_id!=i||e.payload_limit>LASEC_AT_EVENT_PAYLOAD||!ref)return false;}auto overlap=[](uint64_t a,uint64_t an,uint64_t b,uint64_t bn){return a<=UINT64_MAX-bn&&b<=UINT64_MAX-an&&a<b+bn&&b<a+an;};struct Region{uint64_t offset,bytes;};std::vector<Region> rs={{0,sizeof(lasec_at_control_page)},{x.control->descriptor_offset,uint64_t(x.control->descriptor_capacity)*sizeof(lasec_at_endpoint_descriptor)},{x.control->lane_descriptor_offset,uint64_t(x.control->lane_count)*sizeof(lasec_at_lane_descriptor)},{x.control->response_slot_offset,uint64_t(x.control->response_slot_count)*sizeof(lasec_at_response_slot)},{x.control->snapshot_descriptor_offset,uint64_t(x.control->snapshot_count)*sizeof(lasec_at_snapshot_descriptor)},{x.control->c2a_descriptor_offset,sizeof(lasec_at_c2a_descriptor)}};for(uint32_t i=0;i<x.control->lane_count;i++){rs.push_back({x.lanes[i].metadata.offset,x.lanes[i].metadata.bytes});rs.push_back({x.lanes[i].events.offset,x.lanes[i].events.bytes});}for(uint32_t i=0;i<x.control->snapshot_count;i++)rs.push_back({x.snapshots[i].storage.offset,x.snapshots[i].storage.bytes});rs.push_back({x.c2a->metadata.offset,x.c2a->metadata.bytes});rs.push_back({x.c2a->events.offset,x.c2a->events.bytes});for(size_t i=0;i<rs.size();i++)for(size_t j=0;j<i;j++)if(overlap(rs[i].offset,rs[i].bytes,rs[j].offset,rs[j].bytes))return false;v=x;return true;}
